node --input-type=module <<'JS'
import fs from 'node:fs/promises';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { pathToFileURL } from 'node:url';
import assert from 'node:assert/strict';
let networkAttempts=0; globalThis.fetch=async()=>{networkAttempts++;throw Error('Offline diagnosis');};
process.env.PERMITEXT_EVIDENCE_DISCOVERY_BETA='1';
process.env.PERMITEXT_RESEARCH_PASSAGE_SEARCH='0';
process.env.PERMITEXT_RESEARCH_SEMANTIC_SEARCH='0';
const app=await import('./app.mjs'), question='Under the 2022 NYC Mechanical Code, what is the minimum exhaust rate for a private dwelling-unit bathroom for intermittent versus continuous operation?';
const plan=await app.researchCorpusPlanForTurn({question,messages:[],projectFacts:[]}), resources=await app.researchCorpusResources(plan);
const head=execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(), headSource=execFileSync('git',['show',`${head}:permitext-sync-server/evidence-discovery.mjs`],{encoding:'utf8'}), currentSource=await fs.readFile('./evidence-discovery.mjs','utf8');
const sha=x=>createHash('sha256').update(x).digest('hex');
const summarize=async(source,name)=>{
 const absolute=source.replace(/from\s+(['"])(\.\/[^'"]+)\1/g,(_,q,relative)=>`from ${q}${new URL(relative,pathToFileURL(process.cwd()+'/evidence-discovery.mjs')).href}${q}`);
 const m=await import('data:text/javascript;base64,'+Buffer.from(absolute+'\nexport { queryTermWeights, normalizedSearchIndex, topicRoutes };\n//# sourceURL='+name).toString('base64'));
 const reads=[];
 const result=await m.discoverRelevantEvidence({question,catalog:resources.catalog,invertedIndex:resources.invertedIndex,availableCodePrefixes:resources.availableCodePrefixes,limit:12,readSectionBody:async s=>{reads.push(String(s.id));return app.researchBodyForCatalogSection(s);}});
 const weights=m.queryTermWeights(question),index=m.normalizedSearchIndex(resources.invertedIndex),allowed=new Set(resources.catalog.map(x=>String(x.id))),scores=new Map();
 for(const [term,weight] of weights){const posting=index.get(term);if(!posting?.size)continue;const inverse=Math.log((resources.catalog.length+1)/(posting.size+1))+1;for(const id of posting){if(allowed.has(id))scores.set(id,(scores.get(id)||0)+weight*inverse);}}
 const ranked=[...scores].sort((a,b)=>b[1]-a[1]);
 return {matchedRoutes:m.topicRoutes.filter(r=>r.pattern.test(question)).map(r=>r.label),candidates:result.candidates.map((c,i)=>({rank:i+1,id:c.sectionID||c.id,code:c.codePrefix,section:c.sectionNumber,score:c.score})),readCount:reads.length,readTarget:reads.includes('10421'),preliminaryTargetPosition:reads.indexOf('10421'),preliminaryLexicalTargetRank:ranked.findIndex(x=>x[0]==='10421')+1,preliminaryLexicalTargetScore:ranked.find(x=>x[0]==='10421')?.[1]};
};
const legacyHEAD=await summarize(headSource,'head-discovery'), legacyCurrent=await summarize(currentSource,'current-discovery');assert.deepEqual(legacyHEAD,legacyCurrent);
const target=resources.catalog.find(x=>String(x.id)==='10421'), body=await app.researchBodyForCatalogSection(target), text=body.blocks.map(x=>x.plainText||'').join('\n');
process.env.PERMITEXT_RESEARCH_PASSAGE_SEARCH='1';
const indexed=await app.researchCorpusResources(plan), discovery=await import('./evidence-discovery.mjs');
const result=await discovery.discoverRelevantEvidence({question,catalog:indexed.catalog,invertedIndex:indexed.invertedIndex,passageIndex:indexed.passageIndex,availableCodePrefixes:indexed.availableCodePrefixes,limit:12,readSectionBody:app.researchBodyForCatalogSection});
const assembled=await app.assembledResearchEvidenceForTurn({question,messages:[],pinnedEvidence:[],projectFacts:[]}), source=assembled.sources.find(s=>s.codePrefix==='MC'&&s.sectionNumber==='403.3.1.1'), top=result.candidates[0];
assert(source);assert.match(source.text,/20\/50/);assert.match(source.text,/Private dwellings/i);assert.match(source.text,/lower rate.*continuously/i);assert.equal(networkAttempts,0);
console.log(JSON.stringify({head,headDiscoverySHA256:sha(headSource),currentDiscoverySHA256:sha(currentSource),legacyHEAD,legacyCurrent,identityEqual:true,source:{id:10421,title:target.title,bodyBlocks:body.blocks.length,textLength:text.length,textSHA256:sha(text),containsRow:/20\/50/.test(text)},indexed:{passageCount:indexed.passageIndex.passages?.length,topCandidate:{rank:top.rank,sectionID:top.sectionID,codePrefix:top.codePrefix,sectionNumber:top.sectionNumber,score:top.score,indexedPassage:{id:top.indexedPassage.id,sourceTextHash:top.indexedPassage.sourceTextHash,sourceOffsets:top.indexedPassage.sourceOffsets}},assembledTextLength:source.text.length,canonicalContextComplete:source.canonicalContextComplete,containsPrivateDwelling:/Private dwellings/i.test(source.text),containsRow:/20\/50/.test(source.text),containsFootnote:/lower rate.*continuously/i.test(source.text)},networkAttempts}));
JS
